    const mask = switch (allergen) {
        .eggs => 1,
        .peanuts => 2,
        .shellfish => 4,
        .strawberries => 8,
        .tomatoes => 16,
        .chocolate => 32,
        .pollen => 64,
        .cats => 128,
    };
    return (score & mask) != 0;
}

pub fn initAllergenSet(score: usize) EnumSet(Allergen) {
    var set = EnumSet(Allergen).initEmpty();
    const masked_score: u8 = @intCast(score & 0xFF);

    const allergens = [_]Allergen{
        .eggs,
        .peanuts,
        .shellfish,
        .strawberries,
        .tomatoes,
        .chocolate,
        .pollen,
        .cats,
    };

    for (allergens) |allergen| {
        if (isAllergicTo(masked_score, allergen)) {
            set.put(allergen);
        }
    }
    return set;
}
```

